import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws when registering a tool with an invalid inputSchema', () => {
    const registry = new ToolRegistry();
    const invalidSchema = {
      type: 'object',
      properties: {
        count: {type: 'invalid-type'},
      },
    };

    expect(() => {
      registry.register(
        {
          name: 'invalid_tool',
          description: 'A tool with an invalid schema',
          inputSchema: invalidSchema as any,
        },
        async () => 'result'
      );
    }).toThrow(/invalid_tool/);
  });

  it('rejects input missing a required property', async () => {
    const registry = new ToolRegistry();
    let called = false;
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {req: {type: 'string'}},
          required: ['req'],
        },
      },
      async () => {
        called = true;
        return 'ok';
      }
    );

    const response = await registry.execute('test_tool', {});
    expect(response.result).toMatch(/req/);
    expect(response.result).toMatch(/required/i);
    expect(called).toBe(false);
  });

  it('passes through extra properties', async () => {
    const registry = new ToolRegistry();
    let capturedInput: any;
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {req: {type: 'string'}},
        },
      },
      async input => {
        capturedInput = input;
        return 'ok';
      }
    );

    await registry.execute('test_tool', {req: 'val', extra: 'stuff'});
    expect(capturedInput).toEqual({req: 'val', extra: 'stuff'});
  });

  it('rejects wrong-typed fields without leaking values', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {num: {type: 'number'}},
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('test_tool', {num: 'not-a-number'});
    expect(response.result).toMatch(/num/);
    expect(response.result).toMatch(/number/);
    expect(response.result).not.toMatch(/not-a-number/);
  });

  it('re-validates function-valued tool definitions', async () => {
    const registry = new ToolRegistry();
    let schema: any = {
      type: 'object',
      properties: {a: {type: 'string'}},
      required: ['a'],
    };

    registry.register(() => ({name: 'dynamic', description: 'desc', inputSchema: schema}), async () => 'ok');

    // First call with first schema
    const resp1 = await registry.execute('dynamic', {a: 'val'});
    expect(resp1.result).toBe('ok');

    const resp2 = await registry.execute('dynamic', {});
    expect(resp2.result).toMatch(/a/);

    // Change schema
    schema = {
      type: 'object',
      properties: {b: {type: 'string'}},
      required: ['b'],
    };

    const resp3 = await registry.execute('dynamic', {b: 'val'});
    expect(resp3.result).toBe('ok');

    const resp4 = await registry.execute('dynamic', {a: 'val'});
    expect(resp4.result).toMatch(/b/);
  });
});

